/* GLOBE VIEWER - 3D Interactive Earth Globe */

const EARTH_TEXTURE_B64 = "";
const TOPOLOGY_TEXTURE_B64 = "";

class GlobeViewer {
  constructor(container) {
    this.container = container;
    this.width = container.clientWidth || 600;
    this.height = container.clientHeight || 600;
    this.is2DFallback = false;
    this.currentMarker2D = null;
    this.currentLabel2D = null;
    this.imageOverlay2D = null;
    this.textureReady = false;
    this.pendingFocus = null;
    this.labelsHidden = false;
    this.labelToggleBtn = null;

    if (typeof THREE === 'undefined') { this.init2DFallback(container, 'Three.js not loaded'); return; }

    try {
      const tc = document.createElement('canvas');
      const gl = tc.getContext('webgl') || tc.getContext('experimental-webgl');
      if (!gl) throw new Error('No WebGL');
    } catch (e) { this.init2DFallback(container, 'WebGL not available'); return; }

    this.showLoadingOverlay();

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(45, this.width / this.height, 0.1, 1000);
    this.camera.position.set(0, 0, 3);

    this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    this.renderer.setSize(this.width, this.height);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    container.appendChild(this.renderer.domElement);

    this.renderer.domElement.addEventListener('webglcontextlost', (e) => { e.preventDefault(); if(this.animationId) cancelAnimationFrame(this.animationId); });
    this.renderer.domElement.addEventListener('webglcontextrestored', () => { this.animate(); });

    this.createStars();
    const ambient = new THREE.AmbientLight(0xffffff, 0.6);
    this.scene.add(ambient);
    const directional = new THREE.DirectionalLight(0xffffff, 0.8);
    directional.position.set(5, 3, 5);
    this.scene.add(directional);

    this.earthGroup = new THREE.Group();
    this.earthGroup.rotation.order = 'YXZ';
    this.scene.add(this.earthGroup);

    const geometry = new THREE.SphereGeometry(1, 96, 96);
    this.earthMaterial = new THREE.MeshPhongMaterial({ color: 0x2a4a6a, shininess: 8, specular: 0x222222 });
    this.earth = new THREE.Mesh(geometry, this.earthMaterial);
    this.earthGroup.add(this.earth);

    this.markerGroup = new THREE.Group();
    this.earthGroup.add(this.markerGroup);
    this.currentMarker = null;
    this.currentLabel = null;
    this.overlayEl = null;

    this.targetRotation = { x: 0, y: 0 };
    this.currentRotation = { x: 0, y: 0 };
    this.targetCameraZ = 3;
    this.isAnimating = false;
    this.isDragging = false;

    this.setupInteraction();
    this.animationId = null;
    this.animate();
    this.loadTextures();
    this.createLabelToggleButton();

    this.resizeHandler = () => this.resize();
    window.addEventListener('resize', this.resizeHandler);
    setTimeout(() => this.resize(), 200);
    setTimeout(() => this.resize(), 500);
  }

  showLoadingOverlay() {
    const o = document.createElement('div');
    o.className = 'globe-loading-overlay';
    o.innerHTML = '<div class="globe-spinner"></div><div class="globe-loading-text">Loading 3D Earth...</div>';
    this.container.appendChild(o);
    this.loadingOverlay = o;
  }

  hideLoadingOverlay() {
    if (this.loadingOverlay && this.loadingOverlay.parentNode) {
      this.loadingOverlay.style.opacity = '0';
      const el = this.loadingOverlay;
      setTimeout(() => { if (el && el.parentNode) el.parentNode.removeChild(el); }, 300);
      this.loadingOverlay = null;
    }
  }

  loadTextures() {
    if (!GlobeViewer.textureCache) GlobeViewer.textureCache = { earth: null, topology: null, loading: false, loaded: false };
    if (GlobeViewer.textureCache.loaded) { this.applyTextures(GlobeViewer.textureCache.earth, GlobeViewer.textureCache.topology); return; }
    if (GlobeViewer.textureCache.loading) {
      const ci = setInterval(() => { if (GlobeViewer.textureCache.loaded) { clearInterval(ci); this.applyTextures(GlobeViewer.textureCache.earth, GlobeViewer.textureCache.topology); } }, 100);
      return;
    }
    GlobeViewer.textureCache.loading = true;
    const earthUrl = 'data:image/jpeg;base64,' + EARTH_TEXTURE_B64;
    const loader = new THREE.TextureLoader();
    loader.load(earthUrl, (tex) => {
      GlobeViewer.textureCache.earth = tex;
      if (GlobeViewer.textureCache.topology) { GlobeViewer.textureCache.loaded = true; GlobeViewer.textureCache.loading = false; }
      this.applyTextures(tex, GlobeViewer.textureCache.topology);
    }, undefined, () => {
      loader.load(earthUrl, (tex2) => { GlobeViewer.textureCache.earth = tex2; GlobeViewer.textureCache.loaded = true; GlobeViewer.textureCache.loading = false; this.applyTextures(tex2, GlobeViewer.textureCache.topology); });
    });
    const topoUrl = 'data:image/jpeg;base64,' + TOPOLOGY_TEXTURE_B64;
    loader.load(topoUrl, (tex) => {
      GlobeViewer.textureCache.topology = tex;
      if (GlobeViewer.textureCache.earth) { GlobeViewer.textureCache.loaded = true; GlobeViewer.textureCache.loading = false; }
      this.applyTextures(GlobeViewer.textureCache.earth, tex);
    }, undefined, () => {});
  }

  applyTextures(earthTex, topoTex) {
    if (earthTex && !this.earthMaterial.map) {
      this.earthMaterial.map = earthTex;
      this.earthMaterial.color = new THREE.Color(0xffffff);
      if (topoTex) { this.earthMaterial.bumpMap = topoTex; this.earthMaterial.bumpScale = 0.02; }
      this.earthMaterial.needsUpdate = true;
    }
    if (!this.textureReady) {
      this.textureReady = true;
      this.hideLoadingOverlay();
      if (this.pendingFocus) { this.focusOn(this.pendingFocus.lat, this.pendingFocus.lng, this.pendingFocus.label, this.pendingFocus.zoom); this.pendingFocus = null; }
    }
  }

  createStars() {
    const sg = new THREE.BufferGeometry();
    const n = 1500;
    const p = new Float32Array(n * 3);
    for (let i = 0; i < n; i++) {
      const r = 50 + Math.random() * 50, t = Math.random() * Math.PI * 2, ph = Math.acos(2 * Math.random() - 1);
      p[i*3]=r*Math.sin(ph)*Math.cos(t); p[i*3+1]=r*Math.sin(ph)*Math.sin(t); p[i*3+2]=r*Math.cos(ph);
    }
    sg.setAttribute('position', new THREE.BufferAttribute(p, 3));
    this.stars = new THREE.Points(sg, new THREE.PointsMaterial({ color: 0xffffff, size: 0.3, transparent: true, opacity: 0.6 }));
    this.scene.add(this.stars);
  }

  latLngToVector3(lat, lng, radius = 1) {
    const la = lat * Math.PI / 180, ln = lng * Math.PI / 180;
    const x = radius * Math.cos(la) * Math.cos(ln);
    const y = radius * Math.sin(la);
    const z = -radius * Math.cos(la) * Math.sin(ln);
    return new THREE.Vector3(x, y, z);
  }

  focusOn(lat, lng, label, zoom = 2.5) {
    if (this.is2DFallback) { this.focusOn2D(lat, lng, label); return; }
    if (!this.textureReady) this.pendingFocus = { lat, lng, label, zoom };
    this.targetRotation.y = -Math.PI/2 - lng * Math.PI / 180;
    this.targetRotation.x = lat * Math.PI / 180;
    this.targetCameraZ = Math.max(1.6, Math.min(5, zoom));
    this.isAnimating = true;
    if (label) this.setMarker(lat, lng, label);
  }

  setMarker(lat, lng, labelText) {
    if (this.currentMarker) { this.markerGroup.remove(this.currentMarker); this.currentMarker = null; }
    if (this.currentLabel) { this.markerGroup.remove(this.currentLabel); this.currentLabel = null; }
    const pos = this.latLngToVector3(lat, lng, 1.0);
    const normal = pos.clone().normalize();
    const sh = 0.12;
    const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.006, sh, 8), new THREE.MeshBasicMaterial({ color: 0xfbbf24 }));
    stem.position.copy(pos).add(normal.clone().multiplyScalar(sh/2));
    stem.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0), normal);
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.035, 20, 20), new THREE.MeshBasicMaterial({ color: 0xfbbf24 }));
    head.position.copy(pos).add(normal.clone().multiplyScalar(sh));
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.04, 0.07, 32), new THREE.MeshBasicMaterial({ color: 0xfbbf24, side: THREE.DoubleSide, transparent: true, opacity: 0.5 }));
    ring.position.copy(pos).multiplyScalar(1.005); ring.lookAt(0,0,0);
    const mg = new THREE.Group(); mg.add(stem); mg.add(head); mg.add(ring);
    this.currentMarker = mg; this.markerGroup.add(mg);
    if (labelText) { this.currentLabel = this.createLabel(labelText, pos); this.currentLabel.visible = !this.labelsHidden; this.markerGroup.add(this.currentLabel); }
  }

  createLabel(text, position) {
    const c = document.createElement('canvas'); const ctx = c.getContext('2d');
    ctx.font = 'bold 28px Segoe UI, sans-serif';
    const m = ctx.measureText(text); const pad = 20;
    c.width = Math.ceil(m.width) + pad*2; c.height = 48;
    ctx.font = 'bold 28px Segoe UI, sans-serif';
    ctx.fillStyle = 'rgba(15,23,42,0.92)'; ctx.fillRect(0,0,c.width,c.height);
    ctx.strokeStyle = '#38bdf8'; ctx.lineWidth = 3; ctx.strokeRect(1.5,1.5,c.width-3,c.height-3);
    ctx.fillStyle = '#38bdf8'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(text, c.width/2, c.height/2);
    const tex = new THREE.CanvasTexture(c); tex.minFilter = THREE.LinearFilter;
    const label = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
    const n = position.clone().normalize();
    label.position.copy(position).add(n.multiplyScalar(0.22));
    const a = c.width / c.height; const lw = 0.7 * Math.min(a, 4);
    label.scale.set(lw, lw/a, 1);
    return label;
  }

  createLabelToggleButton() {
    const btn = document.createElement('button');
    btn.className = 'globe-toggle-label-btn';
    btn.textContent = 'Hide Label';
    btn.title = 'Hide the location name so students can identify it themselves';
    btn.addEventListener('click', (e) => { e.stopPropagation(); this.toggleLabels(); });
    this.container.appendChild(btn);
    this.labelToggleBtn = btn;
  }

  toggleLabels() {
    this.labelsHidden = !this.labelsHidden;
    if (this.currentLabel) this.currentLabel.visible = !this.labelsHidden;
    if (this.labelToggleBtn) {
      if (this.labelsHidden) { this.labelToggleBtn.textContent = 'Show Label'; this.labelToggleBtn.classList.add('labels-hidden'); }
      else { this.labelToggleBtn.textContent = 'Hide Label'; this.labelToggleBtn.classList.remove('labels-hidden'); }
    }
  }

  showFullScreenImage(imageUrl, caption) {
    if (this.is2DFallback) { this.showFullScreenImage2D(imageUrl, caption); return; }
    this.clearFullScreenImage();
    if (this.renderer && this.renderer.domElement) this.renderer.domElement.style.display = 'none';
    const o = document.createElement('div'); o.className = 'globe-fullscreen-image';
    o.innerHTML = '<img src="'+imageUrl+'" alt="'+(caption||'')+'" />' + (caption ? '<div class="globe-fullscreen-caption">'+caption+'</div>' : '');
    this.container.appendChild(o); this.overlayEl = o;
  }

  clearFullScreenImage() {
    if (this.is2DFallback) { this.clearFullScreenImage2D(); return; }
    if (this.overlayEl && this.overlayEl.parentNode) this.overlayEl.parentNode.removeChild(this.overlayEl);
    this.overlayEl = null;
    if (this.renderer && this.renderer.domElement) this.renderer.domElement.style.display = '';
  }

  showImageOverlay(u,c) { this.showFullScreenImage(u,c); }
  clearImageOverlay() { this.clearFullScreenImage(); }

  setupInteraction() {
    const canvas = this.renderer.domElement; let pX=0, pY=0;
    const dn=(e)=>{this.isDragging=true;this.isAnimating=false;pX=e.clientX;pY=e.clientY;canvas.style.cursor='grabbing';};
    const mv=(e)=>{if(!this.isDragging)return;this.targetRotation.y+=(e.clientX-pX)*0.005;this.targetRotation.x=Math.max(-Math.PI/2,Math.min(Math.PI/2,this.targetRotation.x+(e.clientY-pY)*0.005));this.currentRotation.y=this.targetRotation.y;this.currentRotation.x=this.targetRotation.x;pX=e.clientX;pY=e.clientY;};
const up=()=>{this.isDragging=false;canvas.style.cursor='grab';};
    canvas.addEventListener('mousedown',dn); window.addEventListener('mousemove',mv); window.addEventListener('mouseup',up);
    canvas.addEventListener('touchstart',(e)=>{if(e.touches.length===1)dn(e.touches[0]);},{passive:true});
    canvas.addEventListener('touchmove',(e)=>{if(e.touches.length===1){e.preventDefault();mv(e.touches[0]);}},{passive:false});
    canvas.addEventListener('touchend',up);
    canvas.addEventListener('wheel',(e)=>{e.preventDefault();this.targetCameraZ=Math.max(1.6,Math.min(5,this.targetCameraZ+e.deltaY*0.002));},{passive:false});
    canvas.style.cursor='grab';
  }

  animate() {
    this.animationId = requestAnimationFrame(()=>this.animate());
    const l=0.06;
    this.currentRotation.x+=(this.targetRotation.x-this.currentRotation.x)*l;
    this.currentRotation.y+=(this.targetRotation.y-this.currentRotation.y)*l;
    this.camera.position.z+=(this.targetCameraZ-this.camera.position.z)*l;
    this.earthGroup.rotation.x=this.currentRotation.x; this.earthGroup.rotation.y=this.currentRotation.y;
    if(!this.isAnimating&&!this.isDragging&&!this.currentMarker) this.targetRotation.y+=0.0003;
    if(this.isAnimating){const dx=Math.abs(this.targetRotation.x-this.currentRotation.x),dy=Math.abs(this.targetRotation.y-this.currentRotation.y),dz=Math.abs(this.targetCameraZ-this.camera.position.z);if(dx<0.001&&dy<0.001&&dz<0.001)this.isAnimating=false;}
    if(this.stars) this.stars.rotation.y+=0.00005;
    this.renderer.render(this.scene,this.camera);
  }

  resize() {
    if(!this.container)return; this.width=this.container.clientWidth||600; this.height=this.container.clientHeight||600;
    if(this.is2DFallback)return; if(!this.camera||!this.renderer)return;
    this.camera.aspect=this.width/this.height; this.camera.updateProjectionMatrix(); this.renderer.setSize(this.width,this.height);
  }

  init2DFallback(container, msg) {
    this.is2DFallback=true; container.innerHTML=''; container.style.background='#0a1628'; container.style.position='relative'; container.style.overflow='hidden';
    const img=document.createElement('img'); img.src='data:image/jpeg;base64,'+EARTH_TEXTURE_B64; img.alt='Earth map';
    img.style.cssText='width:100%;height:100%;object-fit:contain;display:block;opacity:0.85;';
    container.appendChild(img); this.mapImg2D=img;
    const n=document.createElement('div'); n.style.cssText='position:absolute;top:8px;left:8px;background:rgba(251,191,36,0.15);border:1px solid #fbbf24;color:#fbbf24;padding:4px 10px;border-radius:6px;font-size:11px;font-weight:600;z-index:5;'; n.textContent='2D mode'; container.appendChild(n);
  }

  focusOn2D(lat,lng,label) {
    if(this.currentMarker2D){this.currentMarker2D.remove();this.currentMarker2D=null;}
    if(this.currentLabel2D){this.currentLabel2D.remove();this.currentLabel2D=null;}
    const x=((lng+180)/360)*100, y=((90-lat)/180)*100;
    const d=document.createElement('div'); d.style.cssText='position:absolute;left:'+x+'%;top:'+y+'%;width:14px;height:14px;margin:-7px 0 0 -7px;background:#fbbf24;border:2px solid #fff;border-radius:50%;box-shadow:0 0 12px #fbbf24;z-index:10;animation:globe-pulse-2d 1.5s ease-in-out infinite;'; this.container.appendChild(d); this.currentMarker2D=d;
    if(label&&!this.labelsHidden){const l=document.createElement('div');l.style.cssText='position:absolute;left:'+x+'%;top:calc('+y+'% - 35px);transform:translateX(-50%);background:rgba(15,23,42,0.92);border:2px solid #38bdf8;color:#38bdf8;padding:5px 12px;border-radius:6px;font-size:12px;font-weight:700;white-space:nowrap;z-index:11;box-shadow:0 4px 16px rgba(0,0,0,0.5);';l.textContent=label;this.container.appendChild(l);this.currentLabel2D=l;}
  }

  showFullScreenImage2D(url,cap){this.clearFullScreenImage2D();if(this.mapImg2D)this.mapImg2D.style.display='none';if(this.currentMarker2D)this.currentMarker2D.style.display='none';if(this.currentLabel2D)this.currentLabel2D.style.display='none';const o=document.createElement('div');o.className='globe-fullscreen-image';o.innerHTML='<img src="'+url+'" alt="'+(cap||'')+'" />'+(cap?'<div class="globe-fullscreen-caption">'+cap+'</div>':'');this.container.appendChild(o);this.imageOverlay2D=o;}
  clearFullScreenImage2D(){if(this.imageOverlay2D&&this.imageOverlay2D.parentNode)this.imageOverlay2D.parentNode.removeChild(this.imageOverlay2D);this.imageOverlay2D=null;if(this.mapImg2D)this.mapImg2D.style.display='';if(this.currentMarker2D)this.currentMarker2D.style.display='';if(this.currentLabel2D)this.currentLabel2D.style.display='';}

  dispose() {
    if(this.animationId)cancelAnimationFrame(this.animationId);
    window.removeEventListener('resize',this.resizeHandler);
    this.clearFullScreenImage();
    if(this.loadingOverlay&&this.loadingOverlay.parentNode)this.loadingOverlay.parentNode.removeChild(this.loadingOverlay);
    if(this.labelToggleBtn&&this.labelToggleBtn.parentNode)this.labelToggleBtn.parentNode.removeChild(this.labelToggleBtn);
    if(this.renderer){this.renderer.dispose();if(this.renderer.domElement.parentNode)this.renderer.domElement.parentNode.removeChild(this.renderer.domElement);}
    this.scene=null;this.earth=null;this.earthGroup=null;
  }
}

GlobeViewer.textureCache = { earth: null, topology: null, loading: false, loaded: false };
window.GlobeViewer = GlobeViewer;
